'use strict';
let currentAuth=null,csrfToken='',authPermissions=null,userRows=[],connectionDrafts=[],isSetup=false,publicDemo=false;
const roleLabels={admin:'Admin',warehouse:'Warehouse',finance:'Finance'};
const allowedViews={admin:['overview','orders','fulfillment','inventory','reports','connections','blueprint','users'],warehouse:['orders','fulfillment','inventory'],finance:['overview','orders','reports']};
const roleText={admin:'จัดการทั้งหมด รวมผู้ใช้และการเชื่อมต่อ',warehouse:'จัดการออเดอร์ หยิบแพ็ก จัดส่ง และสต๊อก',finance:'ดูรายงานการเงินและออเดอร์ ไม่แก้ไขงานคลัง'};
const canView=v=>!!currentAuth&&allowedViews[currentAuth.role]?.includes(v);
const canAction=a=>!!currentAuth&&authPermissions?.actions?.includes(a);
const isFinanceVisible=()=>['admin','finance'].includes(currentAuth?.role);
const channelAssets={'Shopee':'shopee.svg','Lazada':'lazada.svg','TikTok Shop':'tiktok.svg','Facebook':'facebook.svg','LINE OA':'line.png'};
channelLogo=name=>channelAssets[name]?`<span class="channel-logo ${CHANNELS.find(c=>c.name===name)?.key||''}"><img src="channels/${channelAssets[name]}" alt="${esc(name)}"></span>`:`<span class="channel-logo generic">${icon(name==='Review'?'users':'box')}</span>`;
const mark=()=>'<div class="brand-card"><img src="brand-icon.png" alt="โลโก้ Order Hub ใบหน้าคุณลุง"><div><strong>ORDER HUB</strong><small>COMMERCE WORKSPACE</small></div></div>';
async function api(path,method='GET',body){const response=await fetch('/api'+path,{method,credentials:'same-origin',headers:method==='GET'?{}:{'Content-Type':'application/json','X-CSRF-Token':csrfToken},body:body===undefined?undefined:JSON.stringify(body)});const out=await response.json();if(!response.ok){if(response.status===401&&currentAuth){clearSession();showLogin('เซสชันหมดอายุ กรุณาเข้าสู่ระบบใหม่')}throw Error(out.error||'ไม่สามารถดำเนินการได้')}return out}
function clearSession(){clearTimeout(toast.timer);document.getElementById('toast').classList.remove('show');currentAuth=null;csrfToken='';authPermissions=null;orders.splice(0);PRODUCTS.splice(0);payouts.splice(0);expenses.splice(0);audit=[];userRows=[];connectionDrafts=[];state.selected.clear();document.getElementById('dialog').close()}
async function refreshData(){const out=await api('/state');currentAuth=out.user;authPermissions=out.permissions;const d=out.data;PRODUCTS.splice(0,PRODUCTS.length,...d.products);orders.splice(0,orders.length,...d.orders);payouts.splice(0,payouts.length,...(d.payouts||[]));expenses.splice(0,expenses.length,...(d.expenses||[]));audit=d.audit;syncCount=d.syncCount;stockRevision=d.stockRevision;stockEvents=d.stockEvents;blockedChannel=d.blockedChannel;lastStock=centralSnapshot();for(const k of Object.keys(publishedStock))delete publishedStock[k];Object.assign(publishedStock,d.publishedStock);if(currentAuth.role==='admin'){const c=await api('/connections');connectionDrafts=c.drafts}if(!canView(state.view))state.view=currentAuth.role==='warehouse'?'orders':'overview';}
function showLogin(error=''){document.getElementById('app').innerHTML=`<div class="auth-layout"><section class="auth-art"><img src="brand-logo.jpeg" alt="มาสคอต Order Hub ถือกล่องพัสดุ"><div class="auth-art-caption"><strong>ทุกออเดอร์<br>พร้อมไปต่อ</strong><span>รวมงานขาย สต๊อก และจัดส่งไว้ที่เดียว</span></div></section><main class="auth-main"><div class="auth-form-wrap">${mark()}<div class="auth-heading"><div class="eyebrow">${isSetup?'WELCOME TO YOUR WORKSPACE':'YOUR WORKSPACE, CONNECTED'}</div><h1>${isSetup?'เริ่มต้นด้วยบัญชี Admin':'เข้าสู่ระบบ'}</h1><p>${isSetup?'สร้างผู้ดูแลคนแรก แล้วเพิ่มบัญชี Warehouse และ Finance ได้จากเมนูผู้ใช้':'เข้าสู่พื้นที่ทำงานตามสิทธิ์ของคุณ'}</p></div><form id="login-form" class="auth-form">${isSetup?'<label class="field">ชื่อที่แสดง<input name="name" required maxlength="80" autocomplete="name" placeholder="เช่น ผู้ดูแลระบบ"></label>':''}<label class="field">ชื่อผู้ใช้<input name="username" required minlength="3" maxlength="40" autocomplete="username" placeholder="${isSetup?'เช่น admin':'กรอกชื่อผู้ใช้'}" pattern="(?:[a-zA-Z0-9._]|-){3,40}"></label><label class="field">รหัสผ่าน<div class="password-input"><input name="password" id="login-password" type="password" required ${isSetup?'minlength="12"':''} maxlength="128" autocomplete="${isSetup?'new-password':'current-password'}" placeholder="${isSetup?'อย่างน้อย 12 ตัวอักษร':'กรอกรหัสผ่าน'}"><button type="button" id="show-password">แสดง</button></div></label>${isSetup?'<label class="field">ยืนยันรหัสผ่าน<input name="confirm" type="password" minlength="12" maxlength="128" required autocomplete="new-password" placeholder="กรอกรหัสผ่านอีกครั้ง"></label>':''}<div class="auth-error" id="auth-error" role="alert">${esc(error)}</div><button class="btn primary" type="submit">${isSetup?'สร้างบัญชีและเริ่มใช้งาน':'เข้าสู่ระบบ'}</button></form><div class="auth-role-row"><span>Admin</span><span>Warehouse</span><span>Finance</span></div><p class="auth-footer">บัญชีและสิทธิ์บันทึกในเครื่องนี้<br>ข้อมูลออเดอร์ยังเป็นตัวอย่าง · ยังไม่เชื่อมร้านค้าจริง</p></div></main></div>`;document.getElementById('show-password').onclick=()=>{let p=document.getElementById('login-password');p.type=p.type==='password'?'text':'password';document.getElementById('show-password').textContent=p.type==='password'?'แสดง':'ซ่อน'};document.getElementById('login-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),button=e.target.querySelector('button[type=submit]'),error=document.getElementById('auth-error');error.textContent='';if(isSetup&&f.get('password')!==f.get('confirm')){error.textContent='รหัสผ่านยืนยันไม่ตรงกัน';return}button.disabled=true;try{const r=await api(isSetup?'/auth/setup':'/auth/login','POST',{username:f.get('username'),name:f.get('name'),password:f.get('password')});currentAuth=r.user;csrfToken=r.csrf;authPermissions=r.permissions;isSetup=false;state.view=currentAuth.role==='warehouse'?'orders':'overview';await refreshData();shell()}catch(err){error.textContent=err.message;button.disabled=false}}}
async function logout(){try{await api('/auth/logout','POST',{})}catch{}clearSession();showLogin()}
const originalShell=shell;shell=function(){if(!currentAuth){showLogin();return}if(!canView(state.view))state.view=currentAuth.role==='warehouse'?'orders':'overview';originalShell();const brand=document.querySelector('.brand-mark');brand.innerHTML='<img class="brand-logo" src="brand-icon.png" alt="โลโก้ Order Hub ใบหน้าคุณลุง">';document.querySelector('.workspace').innerHTML=`<div class="workspace-avatar">OH</div><div>${roleLabels[currentAuth.role]}<small>${esc(currentAuth.name)}</small></div>`;document.querySelectorAll('.nav[data-view]').forEach(n=>{if(!canView(n.dataset.view))n.remove()});if(currentAuth.role==='admin'){let n=document.createElement('button');n.className='nav '+(state.view==='users'?'active':'');n.innerHTML=icon('users')+'ผู้ใช้และสิทธิ์';n.onclick=()=>changeView('users');document.querySelector('.sidebar nav').append(n)}document.querySelector('.top-right').innerHTML=`<span class="demo-badge">ข้อมูลสาธิต</span><button class="account-button" id="account-menu"><span class="avatar">${esc(currentAuth.name.slice(0,1))}</span><span><strong>${esc(currentAuth.name)}</strong><small>${roleLabels[currentAuth.role]}</small></span></button><button class="logout-btn" id="logout">ออกจากระบบ</button>`;document.getElementById('logout').onclick=logout;document.getElementById('account-menu').onclick=showAccount;const actions=document.querySelector('.heading .actions');if(state.view==='users')actions.innerHTML=button('เพิ่มผู้ใช้','add-user','plus','primary');if(!canAction('create-order'))document.querySelectorAll('[data-action="new-order"]').forEach(e=>e.remove());if(state.view==='connections'&&currentAuth.role==='admin')actions.innerHTML=button('วิธีเชื่อมต่อช่องทาง','connection-help','book');document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));if(currentAuth.role==='finance')document.querySelectorAll('.flow,[data-queue]').forEach(e=>e.remove());if(state.view==='users')bindUsers();if(typeof bindConnections==='function')bindConnections();};
const baseChangeView=changeView;changeView=async function(v){if(!canView(v)){toast('บัญชีนี้ไม่มีสิทธิ์เข้าถึงหน้านี้');return}try{if(v==='users'){const r=await api('/users');userRows=r.users}baseChangeView(v)}catch(e){toast(e.message)}};
function actionError(e){toast(e.message||String(e))}
async function runAction(action,input={}){if(!canAction(action))throw Error('บัญชีนี้ไม่มีสิทธิ์ทำรายการนี้');const out=await api('/actions','POST',{action,...input,requestId:input.requestId||crypto.randomUUID()});await refreshData();shell();return out.result}
const stockDataOriginal=views.inventory;views.inventory=()=>stockDataOriginal();
const baseOrderTable=orderTable;orderTable=function(){if(currentAuth?.role==='admin')return baseOrderTable();let rows=orderRows(),pages=Math.max(1,Math.ceil(rows.length/12));state.page=Math.min(state.page,pages);const finance=currentAuth.role==='finance';return `<section class="panel"><div class="panel-head"><p>${finance?'สิทธิ์ Finance: ดูรายละเอียดและส่งออกข้อมูลได้':'สิทธิ์ Warehouse: ดูสินค้าและงานจัดส่ง โดยไม่มีข้อมูลยอดขายหรือต้นทุน'}</p></div><div class="table-scroll"><table class="data-table"><thead><tr><th>คำสั่งซื้อ / วันที่</th><th>ช่องทาง</th><th>สินค้า / ผู้รับ</th><th>สถานะ</th><th>กำหนดส่ง</th>${finance?'<th class="num">ยอดขาย</th>':''}</tr></thead><tbody>${rows.slice((state.page-1)*12,state.page*12).map(o=>`<tr><td><button class="order-link" data-order="${o.id}">${o.id}</button><small>${formatDate(o.date)}</small></td><td><div class="product-line">${channelLogo(o.channel)}${o.channel}</div></td><td>${sum(o.items,l=>l.qty)} ชิ้น<small>${esc(o.customer)} · ${o.province}</small></td><td>${badge(o.status)}</td><td>${formatDate(o.deadline)}</td>${finance?`<td class="num">${money(sales(o))}</td>`:''}</tr>`).join('')||`<tr><td colspan="6" class="empty">ไม่พบออเดอร์ตามตัวกรอง</td></tr>`}</tbody></table></div><div class="pagination"><span>${rows.length} ออเดอร์ · หน้า ${state.page}/${pages}</span><div class="actions"><button class="btn small" data-page="-1" ${state.page===1?'disabled':''}>ก่อนหน้า</button><button class="btn small" data-page="1" ${state.page===pages?'disabled':''}>ถัดไป</button></div></div></section>`};
showOrder=function(id){if(!currentAuth)return;let o=orders.find(o=>o.id===id);if(!o)return;state.detailId=id;let actions='';const next={new:['reserve','กันสต๊อก / เข้าคิวหยิบ'],ready:['start-pack','เริ่มแพ็ก'],packing:['open-pack','เปิดจุดแพ็ก'],packed:['dispatch','จำลองส่งมอบขนส่ง'],hold:['resolve','ตรวจและแก้ไข']};let n=next[o.status];if(n&&(canAction(n[0])||n[0]==='open-pack'&&canView('fulfillment')))actions+=button(n[1],n[0]==='start-pack'?'detail-pack':'detail-'+n[0],'','primary');if(canAction('cancel')&&['new','ready','packing','packed','hold'].includes(o.status))actions=button('ยกเลิกออเดอร์','detail-cancel','','danger')+actions;modal(o.id,`${o.channel} · ${formatDate(o.date)}`,`<div class="modal-grid"><div><div class="eyebrow">ผู้รับสินค้า</div>${esc(o.customer)}<p>${o.province}<br>ข้อมูลผู้รับตัวอย่าง</p></div><div><div class="eyebrow">สถานะ</div>${badge(o.status)}<p>${o.reserved?'กันสต๊อกแล้ว':'ไม่มีการกันสต๊อก'}<br>${o.tracking||'ยังไม่มีเลขติดตาม'}</p></div></div>${o.items.map(l=>{let p=PRODUCTS.find(p=>p.sku===l.sku);return `<div class="stat-line"><span>${p.name}<small style="display:block;color:var(--muted)">${l.sku} · ${p.location}</small></span><strong>${l.qty} ชิ้น${isFinanceVisible()?`<small style="display:block;font-size:12px">${money(l.price*l.qty)}</small>`:''}</strong></div>`}).join('')}${isFinanceVisible()?`<div class="stat-line"><span>ส่วนลด / คืนเงิน</span><span>${money(o.discount)} / ${money(o.refund)}</span></div><div class="stat-line total"><span>ยอดขายสุทธิ</span><span>${money(sales(o))}</span></div>`:''}<h3>ประวัติการทำงาน</h3><div class="timeline">${recentLog(o.id).slice().reverse().map(a=>`<article>${esc(a.text)}<small>${a.time} · ${esc(a.actor)}</small></article>`).join('')||'<article>ข้อมูลออเดอร์เริ่มต้นในชุดสาธิต</article>'}</div><div class="modal-actions">${actions}</div>`)};
newOrder=function(){if(!canAction('create-order'))return;modal('เปิดออเดอร์สาธิต','ใช้สต๊อกกลางเดียวกับทุกช่องทาง',`<form id="new-order-form"><div class="modal-grid"><label class="field">ช่องทาง<select name="channel"><option>Facebook</option><option>LINE OA</option><option>Offline sales</option><option>Review</option></select></label><label class="field">ชื่อผู้รับตัวอย่าง<input name="customer" value="ลูกค้าทดลอง" maxlength="60" required></label><label class="field">สินค้า<select name="sku">${PRODUCTS.map(p=>`<option value="${p.sku}">${p.name}</option>`).join('')}</select></label><label class="field">จำนวน<input type="number" name="qty" min="1" max="100" step="1" value="1" required></label><label class="field">จังหวัด<select name="province">${['กรุงเทพมหานคร','เชียงใหม่','นนทบุรี','ชลบุรี','ขอนแก่น','ภูเก็ต'].map(p=>`<option>${p}</option>`).join('')}</select></label></div><p>Review เป็นการส่งฟรี กันสต๊อกทันที และไม่เพิ่มยอดขาย</p><div class="auth-error" id="form-error"></div><div class="modal-actions"><button class="btn primary" type="submit">สร้างออเดอร์</button></div></form>`);const requestId=crypto.randomUUID();let pending=false;document.getElementById('new-order-form').onsubmit=async e=>{e.preventDefault();if(pending)return;pending=true;const submit=e.target.querySelector('button[type=submit]');submit.disabled=true;const b=Object.fromEntries(new FormData(e.target));b.qty=Number(b.qty);b.requestId=requestId;try{const result=await runAction('create-order',b);document.getElementById('dialog').close();Object.assign(state,{from:'',to:'',channel:'',product:'',status:result.status,q:'',page:1});await changeView('orders');toast(result.message)}catch(e){const error=document.getElementById('form-error');if(error)error.textContent=e.message;pending=false;submit.disabled=false}}};
const printableAction=extraAction;
extraAction=async function(a){try{if(a==='add-user'){showUserForm();return}if(a==='connection-help'){connectionHelp();return}if(a==='export'){exportData();return}if(a==='new-order'){newOrder();return}if(['print-label','picklist'].includes(a)){if(!canView('fulfillment'))throw Error('บัญชีนี้ไม่มีสิทธิ์ใช้งานจัดส่ง');printableAction(a);return}const o=orders.find(o=>o.id===(a.startsWith('detail')||a==='confirm-resolve'?state.detailId:state.packId));if(['detail-label','pack-label'].includes(a)){if(!canView('fulfillment'))throw Error('ไม่มีสิทธิ์ใช้งาน');shippingLabel(o);return}if(a==='detail-open-pack'){state.packId=o.id;document.getElementById('dialog').close();await changeView('fulfillment');return}if(a==='detail-resolve'){if(!canAction('resolve'))throw Error('ไม่มีสิทธิ์แก้ไขรายการนี้');showResolve(o);return}if(a==='confirm-resolve'){if(!document.getElementById('resolve-check').checked)throw Error('กรุณายืนยันว่าตรวจข้อมูลแล้ว');let r=await runAction('resolve',{id:o.id,confirmed:true});document.getElementById('dialog').close();toast(r);return}if(a.startsWith('bulk-')){const ids=[...state.selected],map={'bulk-reserve':'reserve','bulk-pack':'start-pack','bulk-dispatch':'dispatch'},type=map[a];if(!ids.length)throw Error('กรุณาเลือกออเดอร์ก่อน');let success=0,fail=0;for(const id of ids){try{await api('/actions','POST',{action:type,id});success++}catch{fail++}}state.selected.clear();await refreshData();shell();toast(`ดำเนินการแล้ว ${success} รายการ · ข้าม ${fail} รายการ`);return}const map={'detail-reserve':'reserve','detail-pack':'start-pack','detail-dispatch':'dispatch','detail-cancel':'cancel','pack-start':'start-pack','pack-complete':'complete-pack','pack-dispatch':'dispatch','retry-stock':'retry-stock','fail-stock':'fail-stock','sync':'simulate-order'};if(map[a]){let result=await runAction(map[a],o?{id:o.id}:{});document.getElementById('dialog').close();toast(typeof result==='string'?result:result.message)}}catch(e){actionError(e)}};
const oldExport=exportData;exportData=function(){if(!currentAuth)return;if(currentAuth.role!=='warehouse'){oldExport();return}if(state.view==='inventory'){csvDownload('OrderHub_inventory.csv',['SKU','สินค้า','คงคลัง','กันไว้','พร้อมขาย'],PRODUCTS.map(p=>[p.sku,p.name,p.stock,reserved(p.sku),available(p.sku)]));return}csvDownload('OrderHub_fulfillment.csv',['ออเดอร์','วันที่','ช่องทาง','ผู้รับ','เบอร์โทร','ที่อยู่','แขวง/ตำบล','เขต/อำเภอ','จังหวัด','รหัสไปรษณีย์','สถานะ','สินค้า/จำนวน','จำนวนชิ้น','กำหนดส่ง','ขนส่ง','เลขติดตาม'],orderRows().map(o=>[o.id,o.date,o.channel,o.customer,o.phone||'',o.shippingAddress?.addressLine||'',o.shippingAddress?.subdistrict||'',o.shippingAddress?.district||'',o.province,o.shippingAddress?.postalCode||'',STATUS[o.status],o.items.map(l=>l.sku+' x '+l.qty).join(' | '),sum(o.items,l=>l.qty),o.deadline,o.carrier,o.tracking]))};
bindViews=function(){document.querySelectorAll('[data-status]').forEach(b=>b.onclick=()=>{state.status=b.dataset.status;state.page=1;state.selected.clear();shell()});document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{state.page+=Number(b.dataset.page);shell()});document.querySelectorAll('[data-select]').forEach(b=>b.onchange=()=>{b.checked?state.selected.add(b.dataset.select):state.selected.delete(b.dataset.select);shell()});const all=document.getElementById('select-all');if(all)all.onchange=()=>{orderRows().slice((state.page-1)*12,state.page*12).forEach(o=>all.checked?state.selected.add(o.id):state.selected.delete(o.id));shell()};const q=document.getElementById('order-search');if(q)q.oninput=()=>{let pos=q.selectionStart;state.q=q.value;state.page=1;state.selected.clear();shell();let n=document.getElementById('order-search');n.focus();n.setSelectionRange(pos,pos)};document.querySelectorAll('[data-pack-id]').forEach(b=>b.onclick=()=>{state.packId=b.dataset.packId;shell()});document.querySelectorAll('[data-scan]').forEach(b=>b.onclick=async()=>{try{await runAction('scan',{id:state.packId,sku:b.dataset.scan});toast('ตรวจสินค้าแล้ว 1 ชิ้น')}catch(e){actionError(e)}});const sf=document.getElementById('scan-form');if(sf)sf.onsubmit=async e=>{e.preventDefault();const sku=document.getElementById('scan-input').value.trim().toUpperCase();try{await runAction('scan',{id:state.packId,sku});document.getElementById('scan-input')?.focus();toast('ตรวจสินค้า '+sku+' แล้ว')}catch(e){actionError(e)}};document.querySelectorAll('[data-report-tab]').forEach(b=>b.onclick=()=>{if(!canView('reports'))return;state.report=b.dataset.reportTab;state.product='';state.province='';shell()});document.querySelectorAll('[data-drill-channel]').forEach(b=>b.onclick=()=>{state.channel=b.dataset.drillChannel;state.status='all';state.q='';changeView('orders')});document.querySelectorAll('[data-drill-product]').forEach(b=>b.onclick=()=>{state.product=b.dataset.drillProduct;state.status='all';state.q='';state.page=1;state.view='orders';shell()});document.querySelectorAll('[data-connection]').forEach(b=>b.onclick=()=>openConnectionWizard(b.dataset.connection));document.querySelectorAll('[data-stock]').forEach(b=>b.onclick=()=>{if(!canAction('stock-receive'))return;const p=PRODUCTS.find(p=>p.sku===b.dataset.stock);modal('รับสินค้าเข้า',p.name,`<form id="stock-form"><label class="field">จำนวนรับเข้า (ชิ้น)<input type="number" id="stock-qty" min="1" max="10000" value="20" step="1" required></label><div class="auth-error" id="stock-error"></div><div class="modal-actions"><button class="btn primary">บันทึกรับสินค้า</button></div></form>`);const requestId=crypto.randomUUID();let pending=false;document.getElementById('stock-form').onsubmit=async e=>{e.preventDefault();if(pending)return;pending=true;const submit=e.target.querySelector('button');submit.disabled=true;try{await runAction('stock-receive',{sku:p.sku,qty:Number(document.getElementById('stock-qty').value),requestId});document.getElementById('dialog').close();toast('บันทึกรับสินค้าเข้าแล้ว')}catch(e){const error=document.getElementById('stock-error');if(error)error.textContent=e.message;pending=false;submit.disabled=false}}});};
titles.users=['ผู้ใช้และสิทธิ์การใช้งาน','จัดการทีมและกำหนดหน้าที่ให้เหมาะกับงาน'];
views.users=()=>`<div class="user-summary">${Object.keys(roleLabels).map(r=>`<article class="role-card"><h2>${roleLabels[r]}</h2><strong>${userRows.filter(u=>u.role===r&&u.active).length}<span style="font-size:12px;font-weight:400"> คน</span></strong><p>${roleText[r]}</p></article>`).join('')}</div>${panel('บัญชีผู้ใช้งาน','การเปลี่ยนสิทธิ์ ปิดบัญชี หรือเปลี่ยนรหัสผ่าน จะให้ออกจากระบบทุกอุปกรณ์',`<div class="table-scroll"><table class="data-table"><thead><tr><th>ผู้ใช้งาน</th><th>ชื่อผู้ใช้</th><th>สิทธิ์</th><th>สถานะ</th><th></th></tr></thead><tbody>${userRows.map(u=>`<tr><td><strong>${esc(u.name)}</strong>${u.id===currentAuth.id?'<small>บัญชีของคุณ</small>':''}</td><td>${esc(u.username)}</td><td><span class="account-role">${roleLabels[u.role]}</span></td><td><span class="user-status">${u.active?'ใช้งานอยู่':'ปิดการใช้งาน'}</span></td><td><button class="text-btn" data-edit-user="${u.id}">ตั้งค่าสิทธิ์</button></td></tr>`).join('')}</tbody></table></div>`)}<div style="margin-top:21px">${panel('สิทธิ์แต่ละระดับ','Admin กำหนดบทบาทให้ผู้ใช้แต่ละคน โดยต้องเหลือ Admin ที่ใช้งานได้อย่างน้อย 1 คน',`<div class="table-scroll"><table class="data-table permissions-table"><thead><tr><th>การใช้งาน</th><th>Admin</th><th>Warehouse</th><th>Finance</th></tr></thead><tbody>${[['ดูออเดอร์','ทั้งหมด','เฉพาะข้อมูลจัดส่ง','ดูได้'],['สร้าง / ยกเลิกออเดอร์','ทำได้','—','—'],['กันสต๊อก / หยิบแพ็ก / จัดส่ง','ทำได้','ทำได้','—'],['รับสินค้าเข้า / ดูสต๊อก','ทำได้','ทำได้','—'],['ยอดขาย / ต้นทุน / การเงิน','ดูและส่งออก','—','ดูและส่งออก'],['เชื่อมต่อช่องทางขาย','จัดการได้','—','—'],['บัญชีผู้ใช้และสิทธิ์','จัดการได้','—','—']].map(row=>`<tr>${row.map((c,i)=>`<td class="${i&&c!=='—'?'permission-check':c==='—'?'permission-no':''}">${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`)}</div>`;
function bindUsers(){document.querySelectorAll('[data-edit-user]').forEach(b=>b.onclick=()=>showUserForm(userRows.find(u=>u.id===b.dataset.editUser)))}
function showUserForm(user){if(currentAuth?.role!=='admin')return;modal(user?'ตั้งค่าสิทธิ์ผู้ใช้':'เพิ่มบัญชีผู้ใช้งาน',user?user.username:'กำหนดบัญชีและสิทธิ์ให้สมาชิกทีม',`<form id="user-form"><div class="modal-grid"><label class="field">ชื่อที่แสดง<input name="name" value="${esc(user?.name||'')}" required maxlength="80"></label><label class="field">ชื่อผู้ใช้<input name="username" value="${esc(user?.username||'')}" ${user?'disabled':''} required pattern="(?:[a-zA-Z0-9._]|-){3,40}" placeholder="เช่น warehouse01"></label><label class="field">สิทธิ์การใช้งาน<select name="role">${Object.keys(roleLabels).map(r=>`<option value="${r}" ${user?.role===r?'selected':''}>${roleLabels[r]}</option>`).join('')}</select></label>${user?`<label class="field">สถานะบัญชี<select name="active"><option value="true" ${user.active?'selected':''}>ใช้งานอยู่</option><option value="false" ${!user.active?'selected':''}>ปิดการใช้งาน</option></select></label>`:''}<label class="field">${user?'ตั้งรหัสผ่านใหม่ (เว้นว่างเพื่อใช้เดิม)':'รหัสผ่านเริ่มต้น'}<input name="password" type="password" autocomplete="new-password" minlength="12" maxlength="128" ${user?'':'required'} placeholder="อย่างน้อย 12 ตัวอักษร"></label></div><p class="form-help" style="margin-top:15px">สมาชิกเปลี่ยนรหัสผ่านเองได้จากชื่อบัญชีมุมขวาบน</p><div class="auth-error" id="user-error"></div><div class="modal-actions"><button class="btn primary">${user?'บันทึกการเปลี่ยนแปลง':'สร้างผู้ใช้'}</button></div></form>`);document.getElementById('user-form').onsubmit=async e=>{e.preventDefault();let f=new FormData(e.target),b={name:f.get('name'),role:f.get('role')};if(user){b.active=f.get('active')==='true';if(f.get('password'))b.password=f.get('password')}else{b.username=f.get('username');b.password=f.get('password')}try{let r=await api(user?'/users/'+user.id:'/users',user?'PATCH':'POST',b);document.getElementById('dialog').close();if(r.sessionRevoked){clearSession();showLogin('สิทธิ์บัญชีเปลี่ยนแล้ว กรุณาเข้าสู่ระบบใหม่');return}userRows=(await api('/users')).users;shell();toast('บันทึกผู้ใช้แล้ว')}catch(e){const error=document.getElementById('user-error');if(error)error.textContent=e.message}}}
function showAccount(){if(!currentAuth)return;modal('บัญชีของคุณ',`${currentAuth.username} · ${roleLabels[currentAuth.role]}`,`<p>${esc(currentAuth.name)}</p><form id="password-form"><div class="wizard-fields"><label class="field">รหัสผ่านปัจจุบัน<input name="currentPassword" type="password" autocomplete="current-password" required maxlength="128"></label><label class="field">รหัสผ่านใหม่<input name="password" type="password" autocomplete="new-password" minlength="12" maxlength="128" required></label><label class="field">ยืนยันรหัสผ่านใหม่<input name="confirm" type="password" autocomplete="new-password" minlength="12" maxlength="128" required></label></div><p class="form-help" style="margin-top:12px">เมื่อเปลี่ยนรหัสผ่านแล้ว จะต้องเข้าสู่ระบบใหม่ทุกอุปกรณ์</p><div class="auth-error" id="password-error"></div><div class="modal-actions"><button class="btn primary">เปลี่ยนรหัสผ่าน</button></div></form>`);document.getElementById('password-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),error=document.getElementById('password-error');if(f.get('password')!==f.get('confirm')){error.textContent='รหัสผ่านยืนยันไม่ตรงกัน';return}try{await api('/auth/password','POST',{currentPassword:f.get('currentPassword'),password:f.get('password')});clearSession();showLogin('เปลี่ยนรหัสผ่านแล้ว กรุณาเข้าสู่ระบบใหม่')}catch(e){error.textContent=e.message}}}
const guardedSummary=()=>({role:currentAuth?.role,demo:true,...(isFinanceVisible()?{summary:stats(filtered()),received:sum(filteredPayouts(),p=>p.net)}:{orderCount:filtered().length,stockUnits:sum(PRODUCTS,p=>p.stock)})});
// The prior demo WebMCP registrar is intentionally not invoked. Every protected read uses API authentication.
async function bootAuth(){if(location.protocol==='file:'){document.getElementById('app').innerHTML=`<main class="login-recovery">${mark()}<h1>เปิด Order Hub ผ่านระบบ Login</h1><p>ฉบับนี้ตรวจสิทธิ์และบันทึกบัญชีผ่านเซิร์ฟเวอร์ในเครื่อง กรุณาเปิดแอปจากตัวเริ่มใช้งาน Order Hub แล้วเข้าสู่ระบบ</p><a class="btn primary" href="http://127.0.0.1:4180/">เปิดหน้าเข้าสู่ระบบ</a></main>`;return}try{const r=await api('/auth/status');isSetup=r.needsSetup;currentAuth=r.user;csrfToken=r.csrf||'';authPermissions=r.permissions;if(currentAuth){await refreshData();shell()}else showLogin()}catch(e){document.getElementById('app').innerHTML=`<main class="login-recovery">${mark()}<h1>ยังเปิดระบบไม่ได้</h1><p>${esc(e.message)}</p><button class="btn primary" id="retry-auth">ลองอีกครั้ง</button></main>`;document.getElementById('retry-auth').onclick=bootAuth}}


// Store context is always established by the authenticated server response.
let currentStore=null,sessionEpoch=0;
const initialStoreHint=(new URLSearchParams(location.search).get('store')||'').trim().toLowerCase();
let loginStoreHint=/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(initialStoreHint)&&initialStoreHint.length>=3&&initialStoreHint.length<=40?initialStoreHint:'';
allowedViews.admin.push('store');
function storeLoginUrl(code){const url=new URL(location.href);url.search='';url.hash='';url.searchParams.set('store',code);return url.href}
function acceptStore(store){currentStore=store||null;if(store?.code){loginStoreHint=store.code;const url=new URL(location.href);url.searchParams.set('store',store.code);history.replaceState(null,'',url)}}
function setPending(form,pending){form.dataset.pending=pending?'true':'';form.querySelectorAll('button[type=submit],button:not([type])').forEach(b=>b.disabled=pending)}
function guardForm(form){if(!form||!form.onsubmit)return;const submit=form.onsubmit;form.onsubmit=async e=>{e.preventDefault();if(form.dataset.pending==='true')return;setPending(form,true);try{await submit(e)}catch(error){if(form.isConnected)toast(error.message)}finally{if(form.isConnected)setPending(form,false)}}}
const originalClearSession=clearSession;
clearSession=function(){sessionEpoch++;if(currentStore?.code)loginStoreHint=currentStore.code;originalClearSession();currentStore=null;syncCount=0;stockRevision=1;stockEvents=[];blockedChannel='';lastStock={};for(const key of Object.keys(publishedStock))delete publishedStock[key];const range=typeof dateRange==='function'?dateRange('7days'):['',TODAY];Object.assign(state,{view:'overview',from:range[0],to:range[1],channel:'',product:'',province:'',status:'all',q:'',page:1,report:'sales',packId:null,detailId:null,mobile:false});state.selected.clear();if(typeof activePreset!=='undefined')activePreset='7days';document.getElementById('toast').textContent='';document.getElementById('dialog-content').innerHTML=''};
function storeSessionChanged(message='บัญชีหรือร้านค้าเปลี่ยนแล้ว กรุณาเข้าสู่ระบบใหม่'){clearSession();showLogin(message)}
api=async function(path,method='GET',body){const epoch=sessionEpoch,headers=method==='GET'?{}:{'Content-Type':'application/json','X-CSRF-Token':csrfToken};if(currentStore?.id&&!['/auth/status','/auth/login','/auth/setup'].includes(path))headers['X-Store-Id']=currentStore.id;const response=await fetch('/api'+path,{method,credentials:'same-origin',headers,body:body===undefined?undefined:JSON.stringify(body)});const out=await response.json();if(epoch!==sessionEpoch)throw Error('เซสชันเปลี่ยนแล้ว กรุณาทำรายการใหม่');if(!response.ok){if(out.code==='SESSION_CHANGED'){storeSessionChanged()}else if(response.status===401&&currentAuth){storeSessionChanged('เซสชันหมดอายุ กรุณาเข้าสู่ระบบใหม่')}throw Error(out.error||'ไม่สามารถดำเนินการได้')}return out};
refreshData=async function(){const epoch=sessionEpoch,expectedStoreId=currentStore?.id,expectedUserId=currentAuth?.id,out=await api('/state');if(epoch!==sessionEpoch)return;if(!out.store||expectedStoreId&&out.store.id!==expectedStoreId||expectedUserId&&out.user?.id!==expectedUserId){storeSessionChanged();throw Error('กรุณาเข้าสู่ระบบร้านที่ต้องการ')}currentAuth=out.user;acceptStore(out.store);authPermissions=out.permissions;const d=out.data;PRODUCTS.splice(0,PRODUCTS.length,...d.products);orders.splice(0,orders.length,...d.orders);payouts.splice(0,payouts.length,...(d.payouts||[]));expenses.splice(0,expenses.length,...(d.expenses||[]));audit=d.audit;syncCount=d.syncCount;stockRevision=d.stockRevision;stockEvents=d.stockEvents;blockedChannel=d.blockedChannel;lastStock=centralSnapshot();for(const key of Object.keys(publishedStock))delete publishedStock[key];Object.assign(publishedStock,d.publishedStock);if(currentAuth.role==='admin'){const c=await api('/connections');if(epoch!==sessionEpoch)return;connectionDrafts=c.drafts}else connectionDrafts=[];if(!canView(state.view))state.view=currentAuth.role==='warehouse'?'orders':'overview'};
showLogin=function(error=''){
document.getElementById('app').innerHTML=`<div class="auth-layout"><section class="auth-art"><img src="brand-logo.jpeg" alt="มาสคอต Order Hub ถือกล่องพัสดุ"><div class="auth-art-caption"><strong>ทุกออเดอร์<br>พร้อมไปต่อ</strong><span>รวมงานขาย สต๊อก และจัดส่งไว้ที่เดียว</span></div></section><main class="auth-main"><div class="auth-form-wrap">${mark()}<div class="auth-heading"><div class="eyebrow">${isSetup?'WELCOME TO YOUR WORKSPACE':'YOUR WORKSPACE, CONNECTED'}</div><h1>${isSetup?'สร้างร้านและบัญชี Admin':'เข้าสู่ระบบร้านค้า'}</h1><p>${isSetup?'เริ่มจากร้านแรก แล้วเพิ่มทีม Warehouse และ Finance ภายในร้านได้':'ระบุรหัสร้านและบัญชีของคุณ เพื่อเข้าพื้นที่ทำงานของร้านนั้น'}</p></div><form id="login-form" class="auth-form">${isSetup?'<label class="field">ชื่อร้าน<input name="storeName" required maxlength="80" autocomplete="organization" placeholder="เช่น ร้านหลักของบริษัท"></label>':''}<label class="field">รหัสร้าน<input name="storeCode" required minlength="3" maxlength="40" pattern="[a-z0-9]+(?:-[a-z0-9]+)*" value="${esc(loginStoreHint)}" autocapitalize="none" spellcheck="false" autocomplete="off" placeholder="เช่น main-store"><span class="form-help">${isSetup?'ใช้ตัวอักษรอังกฤษเล็ก ตัวเลข และขีดกลาง 3–40 ตัว เปลี่ยนภายหลังไม่ได้':'ใช้รหัสร้านที่ Admin แจ้ง หรือเปิดจากลิงก์เข้าสู่ระบบของร้าน'}</span></label>${isSetup?'<label class="field">ชื่อผู้ดูแลร้าน<input name="name" required maxlength="80" autocomplete="name" placeholder="เช่น ผู้ดูแลระบบ"></label>':''}<label class="field">ชื่อผู้ใช้<input name="username" required minlength="3" maxlength="40" autocomplete="username" pattern="(?:[a-zA-Z0-9._]|-){3,40}" placeholder="${isSetup?'เช่น admin':'กรอกชื่อผู้ใช้'}"></label><label class="field">รหัสผ่าน<div class="password-input"><input name="password" id="login-password" type="password" required ${isSetup?'minlength="12"':''} maxlength="128" autocomplete="${isSetup?'new-password':'current-password'}" placeholder="${isSetup?'อย่างน้อย 12 ตัวอักษร':'กรอกรหัสผ่าน'}"><button type="button" id="show-password">แสดง</button></div></label>${isSetup?'<label class="field">ยืนยันรหัสผ่าน<input name="confirm" type="password" minlength="12" maxlength="128" required autocomplete="new-password" placeholder="กรอกรหัสผ่านอีกครั้ง"></label>':''}<div class="auth-error" id="auth-error" role="alert">${esc(error)}</div><button class="btn primary" type="submit">${isSetup?'สร้างร้านและเริ่มใช้งาน':'เข้าสู่ระบบ'}</button></form><div class="auth-role-row"><span>Admin</span><span>Warehouse</span><span>Finance</span></div><p class="auth-footer">บัญชีและข้อมูลแยกตามร้าน<br>ทุกช่องทางของแต่ละร้านใช้สต๊อกกลางของร้านนั้น</p></div></main></div>`;
document.getElementById('show-password').onclick=()=>{const p=document.getElementById('login-password');p.type=p.type==='password'?'text':'password';document.getElementById('show-password').textContent=p.type==='password'?'แสดง':'ซ่อน'};
const form=document.getElementById('login-form');form.onsubmit=async e=>{e.preventDefault();if(form.dataset.pending==='true')return;const f=new FormData(form),error=document.getElementById('auth-error');error.textContent='';if(isSetup&&f.get('password')!==f.get('confirm')){error.textContent='รหัสผ่านยืนยันไม่ตรงกัน';return}setPending(form,true);loginStoreHint=String(f.get('storeCode')).trim().toLowerCase();try{const r=await api(isSetup?'/auth/setup':'/auth/login','POST',{storeCode:loginStoreHint,storeName:f.get('storeName'),username:f.get('username'),name:f.get('name'),password:f.get('password')});clearSession();currentAuth=r.user;acceptStore(r.store);csrfToken=r.csrf;authPermissions=r.permissions;isSetup=false;state.view=currentAuth.role==='warehouse'?'orders':'overview';await refreshData();shell()}catch(err){if(form.isConnected){error.textContent=err.message;setPending(form,false)}}};
};
const storeBaseShell=shell;
shell=function(){storeBaseShell();if(!currentAuth)return;document.querySelector('.workspace').innerHTML=`<div class="workspace-avatar">${icon('box')}</div><div class="store-workspace"><strong title="${esc(currentStore?.name||'')}">${esc(currentStore?.name||'ร้านค้า')}</strong><small>${esc(currentStore?.code||'')} · ${roleLabels[currentAuth.role]}</small></div>`;if(currentAuth.role==='admin'){const nav=document.createElement('button');nav.className='nav '+(state.view==='store'?'active':'');nav.dataset.view='store';nav.innerHTML=icon('box')+'ร้านค้า';nav.onclick=()=>changeView('store');document.querySelector('.sidebar nav').append(nav)}if(state.view==='users'){document.querySelector('.heading .actions').innerHTML=button('เพิ่มผู้ใช้ในร้านนี้','add-user','plus','primary');document.querySelector('[data-action="add-user"]').onclick=()=>showUserForm()}if(state.view==='store'){document.querySelector('.heading .actions').innerHTML=button('สร้างร้านใหม่','create-store','plus','primary');document.querySelector('[data-action="create-store"]').onclick=showCreateStore;bindStore()}};
const storeBaseChangeView=changeView;
changeView=async function(view){if(view==='store'){if(!canView(view)){toast('บัญชีนี้ไม่มีสิทธิ์เข้าถึงหน้านี้');return}try{const out=await api('/store');if(out.store.id!==currentStore?.id){storeSessionChanged();return}acceptStore(out.store)}catch(error){toast(error.message);return}}return storeBaseChangeView(view)};
const storeBaseUsersView=views.users;
views.users=()=>`<div class="store-context-note">${icon('box')}<span>ทีมของร้าน <strong>${esc(currentStore?.name||'')}</strong> · ${esc(currentStore?.code||'')}<small>บัญชีในหน้านี้เข้าถึงเฉพาะข้อมูลร้านนี้</small></span></div>`+storeBaseUsersView();
const storeBaseShowUserForm=showUserForm;
showUserForm=function(user){storeBaseShowUserForm(user);if(currentAuth?.role!=='admin')return;document.querySelector('#dialog .modal-head p').textContent=(user?user.username+' · ':'')+'ร้าน '+currentStore.name;guardForm(document.getElementById('user-form'))};
const storeBaseShowAccount=showAccount;
showAccount=function(){storeBaseShowAccount();if(!currentAuth)return;document.querySelector('#dialog .modal-head p').textContent=currentAuth.username+' · '+roleLabels[currentAuth.role]+' · '+currentStore.code;guardForm(document.getElementById('password-form'))};
titles.store=['ร้านค้า','ดูข้อมูลร้านที่ใช้งาน และสร้างพื้นที่ทำงานแยกสำหรับร้านใหม่'];
views.store=()=>`<div class="store-context-note">${icon('box')}<span>กำลังทำงานในร้าน <strong>${esc(currentStore.name)}</strong><small>ออเดอร์ สต๊อก การเงิน บัญชีผู้ใช้ และการเชื่อมต่อ แยกจากร้านอื่น</small></span></div><div class="store-grid">${panel('ข้อมูลร้านนี้','แก้ชื่อที่แสดงได้ รหัสร้านใช้สำหรับเข้าสู่ระบบ',`<div class="panel-body"><form id="store-settings-form" class="wizard-fields"><label class="field">ชื่อร้าน<input name="name" value="${esc(currentStore.name)}" maxlength="80" required autocomplete="organization"></label><label class="field">รหัสร้าน<input value="${esc(currentStore.code)}" readonly><span class="form-help">รหัสนี้เปลี่ยนไม่ได้ และต้องระบุพร้อมชื่อผู้ใช้เมื่อเข้าสู่ระบบ</span></label><div class="auth-error" id="store-settings-error" role="alert"></div><div class="actions"><button class="btn primary" type="submit">บันทึกชื่อร้าน</button></div></form></div>`)}${panel('ลิงก์เข้าสู่ระบบของร้าน','คัดลอกให้สมาชิกทีม พร้อมชื่อผู้ใช้ที่เพิ่มในร้านนี้',`<div class="panel-body"><label class="field">ลิงก์ร้าน<input id="store-login-url" class="store-link-input" value="${esc(storeLoginUrl(currentStore.code))}" readonly></label><div class="actions" style="margin-top:14px"><button class="btn" id="copy-store-link">คัดลอกลิงก์</button></div><p class="form-help" style="margin-top:17px">ลิงก์ช่วยกรอกรหัสร้านให้เท่านั้น ผู้ใช้ยังต้องเข้าสู่ระบบด้วยบัญชีและรหัสผ่านของร้านนี้</p><div class="wizard-callout"><strong>สต๊อกกลางของร้านเดียวกัน</strong><p>Facebook, Shopee, TikTok Shop, Lazada, LINE OA, Review และ Offline sales ของร้านนี้ ใช้สินค้าคงคลังกองเดียวกัน ส่วนร้านใหม่มีสต๊อกกลางของตัวเอง</p></div></div>`)}</div>${panel('เพิ่มร้านใหม่ที่แยกข้อมูล','เริ่มพื้นที่ทำงานและบัญชี Admin ของร้านใหม่',`<div class="panel-body store-new-row"><div><h3>ทีมและข้อมูลของแต่ละร้านแยกจากกัน</h3><p class="section-sub">ร้านใหม่เริ่มด้วยสินค้าตัวอย่างจำนวน 0 และไม่มีออเดอร์หรือรายงานการเงินเดิม ต้องสร้างบัญชี Admin สำหรับร้านใหม่โดยเฉพาะ</p></div><button class="btn primary" id="new-store-button">${icon('plus')}สร้างร้านใหม่</button></div>`)}`;
async function copyStoreLoginLink(input){try{await navigator.clipboard.writeText(input.value);toast('คัดลอกลิงก์เข้าสู่ระบบแล้ว')}catch{input.focus();input.select();toast('เลือกลิงก์แล้ว กดคัดลอกเพื่อส่งให้ทีม')}}
function bindStore(){const form=document.getElementById('store-settings-form');form.onsubmit=async e=>{e.preventDefault();if(form.dataset.pending==='true')return;const error=document.getElementById('store-settings-error');error.textContent='';setPending(form,true);try{const out=await api('/store','PATCH',{name:String(new FormData(form).get('name')).trim()});if(out.store.id!==currentStore?.id){storeSessionChanged();return}acceptStore(out.store);shell();toast('บันทึกชื่อร้านแล้ว')}catch(err){if(form.isConnected){error.textContent=err.message;setPending(form,false)}}};document.getElementById('copy-store-link').onclick=()=>copyStoreLoginLink(document.getElementById('store-login-url'));document.getElementById('new-store-button').onclick=showCreateStore}
function showCreateStore(){if(currentAuth?.role!=='admin')return;modal('สร้างร้านใหม่','ร้านใหม่จะมีบัญชีผู้ดูแลและข้อมูลของตัวเอง',`<form id="create-store-form"><div class="wizard-callout"><strong>สร้างบัญชี Admin สำหรับร้านใหม่</strong><p>บัญชีปัจจุบันยังอยู่ในร้าน ${esc(currentStore.name)} หลังสร้างสำเร็จ หากต้องการใช้ร้านใหม่ ให้ออกจากระบบแล้วเข้าสู่ระบบด้วยรหัสร้านและบัญชีใหม่</p></div><div class="modal-grid"><label class="field">ชื่อร้านใหม่<input name="storeName" required maxlength="80" placeholder="เช่น ร้านสาขาใหม่" autocomplete="organization"></label><label class="field">รหัสร้านใหม่<input name="storeCode" required minlength="3" maxlength="40" pattern="[a-z0-9]+(?:-[a-z0-9]+)*" placeholder="เช่น new-store" autocapitalize="none" spellcheck="false" autocomplete="off"><span class="form-help">อังกฤษเล็ก ตัวเลข และขีดกลาง 3–40 ตัว เปลี่ยนไม่ได้</span></label><label class="field">ชื่อผู้ดูแลร้านใหม่<input name="name" required maxlength="80" placeholder="ชื่อที่แสดง" autocomplete="off"></label><label class="field">ชื่อผู้ใช้ Admin ของร้านใหม่<input name="username" required minlength="3" maxlength="40" pattern="(?:[a-zA-Z0-9._]|-){3,40}" placeholder="เช่น admin" autocomplete="off"></label><label class="field">รหัสผ่านสำหรับร้านใหม่<input name="password" type="password" required minlength="12" maxlength="128" autocomplete="new-password" placeholder="อย่างน้อย 12 ตัวอักษร"></label><label class="field">ยืนยันรหัสผ่าน<input name="confirm" type="password" required minlength="12" maxlength="128" autocomplete="new-password"></label></div><p class="form-help" style="margin-top:15px">ร้านใหม่มีคลังกลางแยกต่างหาก ไม่ดึงออเดอร์ สต๊อก ผู้ใช้ หรือการเชื่อมต่อจากร้านนี้ไปด้วย</p><div class="auth-error" id="create-store-error" role="alert"></div><div class="modal-actions"><button class="btn primary" type="submit">สร้างร้านและบัญชี Admin</button></div></form>`);const form=document.getElementById('create-store-form');form.onsubmit=async e=>{e.preventDefault();if(form.dataset.pending==='true')return;const f=new FormData(form),error=document.getElementById('create-store-error');error.textContent='';if(f.get('password')!==f.get('confirm')){error.textContent='รหัสผ่านยืนยันไม่ตรงกัน';return}setPending(form,true);const username=String(f.get('username')).trim().toLowerCase();try{const out=await api('/stores','POST',{storeName:f.get('storeName'),storeCode:String(f.get('storeCode')).trim().toLowerCase(),name:f.get('name'),username,password:f.get('password')});const created=out.store;form.reset();modal('สร้างร้านใหม่แล้ว',esc(created.name),`<div class="store-created"><span class="badge packed">สร้างบัญชี Admin แล้ว</span><div class="stat-line"><span>ชื่อร้าน</span><strong>${esc(created.name)}</strong></div><div class="stat-line"><span>รหัสร้าน</span><strong>${esc(created.code)}</strong></div><div class="stat-line"><span>ชื่อผู้ใช้ Admin</span><strong>${esc(username)}</strong></div><label class="field" style="margin-top:20px">ลิงก์เข้าสู่ระบบร้านใหม่<input id="created-store-link" class="store-link-input" readonly value="${esc(storeLoginUrl(created.code))}"></label><div class="actions" style="margin-top:13px"><button class="btn" id="copy-created-store-link">คัดลอกลิงก์ร้านใหม่</button></div><p class="form-help" style="margin-top:19px">คุณยังอยู่ในร้าน ${esc(currentStore.name)} บัญชีร้านใหม่ใช้รหัสผ่านที่เพิ่งตั้งไว้ หากต้องการเปิดร้านใหม่ ให้ออกจากระบบแล้วใช้ลิงก์นี้</p><div class="modal-actions"><button class="btn primary" id="close-created-store">กลับร้านปัจจุบัน</button></div></div>`);document.getElementById('copy-created-store-link').onclick=()=>copyStoreLoginLink(document.getElementById('created-store-link'));document.getElementById('close-created-store').onclick=()=>document.getElementById('dialog').close()}catch(err){if(form.isConnected){error.textContent=err.message;setPending(form,false)}}}}
bootAuth=async function(){if(location.protocol==='file:'){document.getElementById('app').innerHTML=`<main class="login-recovery">${mark()}<h1>เปิด Order Hub ผ่านระบบ Login</h1><p>กรุณาเปิดตัวเริ่มใช้งาน Order Hub แล้วเข้าสู่ระบบร้านค้า</p><a class="btn primary" href="http://127.0.0.1:4180/">เปิดหน้าเข้าสู่ระบบ</a></main>`;return}try{const r=await api('/auth/status');publicDemo=r.publicDemo===true;isSetup=r.needsSetup;loginStoreHint=publicDemo?'':loginStoreHint||r.legacyStoreCode||'';if(!publicDemo&&r.user&&loginStoreHint&&r.store?.code!==loginStoreHint){clearSession();showLogin('เข้าสู่ระบบด้วยบัญชีของร้าน '+loginStoreHint);return}currentAuth=r.user;acceptStore(r.store);csrfToken=r.csrf||'';authPermissions=r.permissions;if(currentAuth){await refreshData();shell()}else showLogin()}catch(error){document.getElementById('app').innerHTML=`<main class="login-recovery">${mark()}<h1>ยังเปิดระบบไม่ได้</h1><p>${esc(error.message)}</p><button class="btn primary" id="retry-auth">ลองอีกครั้ง</button></main>`;document.getElementById('retry-auth').onclick=bootAuth}};
let checkingStoreSession=false;
async function checkStoreSession(){if(!currentAuth||checkingStoreSession||document.visibilityState==='hidden')return;checkingStoreSession=true;const epoch=sessionEpoch,expectedStoreId=currentStore?.id,expectedCsrf=csrfToken;try{const out=await api('/auth/status');if(epoch===sessionEpoch&&(!out.user||out.store?.id!==expectedStoreId||out.csrf!==expectedCsrf))storeSessionChanged()}catch{}finally{checkingStoreSession=false}}
window.addEventListener('focus',checkStoreSession);
document.addEventListener('visibilitychange',checkStoreSession);
document.addEventListener('input',event=>{const input=event.target;if(input instanceof HTMLInputElement&&input.name==='storeCode'){const position=input.selectionStart;input.value=input.value.toLowerCase();if(position!==null)input.setSelectionRange(position,position)}});

// Public previews receive an isolated guest session from the server. Normal
// stores keep the login, passwords and team management above.
const authenticatedAcceptStore=acceptStore;
acceptStore=function(store){
  if(!publicDemo){authenticatedAcceptStore(store);return}
  currentStore=store||null;
  loginStoreHint='';
  const url=new URL(location.href);
  url.searchParams.delete('store');
  history.replaceState(null,'',url);
};

function publicDemoRecovery(message='เปิดพื้นที่ทดลองของคุณอีกครั้งได้เลย'){
  document.body.classList.remove('public-demo-mode');
  document.getElementById('app').innerHTML=`<main class="login-recovery">${mark()}<h1>พื้นที่ทดลองของคุณ</h1><p>${esc(message)}</p><button class="btn primary" id="retry-auth">เปิดพื้นที่ทดลอง</button></main>`;
  document.getElementById('retry-auth').onclick=bootAuth;
}

const authenticatedShowLogin=showLogin;
showLogin=function(error=''){
  if(publicDemo){publicDemoRecovery(error||undefined);return}
  document.body.classList.remove('public-demo-mode');
  authenticatedShowLogin(error);
};

const authenticatedSessionChanged=storeSessionChanged;
storeSessionChanged=function(message){
  if(!publicDemo){authenticatedSessionChanged(message);return}
  clearSession();
  publicDemoRecovery('พื้นที่ทดลองเปลี่ยนหรือหมดเวลา กดเปิดเพื่อทดลองต่อได้');
};

function showPublicDemoReset(){
  if(!publicDemo||!currentAuth)return;
  modal('เริ่มข้อมูลทดลองใหม่','เริ่มต้นอีกครั้งด้วยข้อมูลตัวอย่าง',`<p>ออเดอร์และรายการที่คุณเพิ่มในพื้นที่ทดลองนี้จะถูกล้าง และกลับเป็นข้อมูลตัวอย่างเริ่มต้น</p><p class="form-help">ข้อมูลของผู้เข้าชมคนอื่นไม่เปลี่ยนแปลง</p><form id="demo-reset-form"><div class="auth-error" id="demo-reset-error" role="alert"></div><div class="modal-actions"><button class="btn" type="button" id="cancel-demo-reset">กลับไปทดลองต่อ</button><button class="btn primary" type="submit" id="confirm-demo-reset">เริ่มใหม่</button></div></form>`);
  document.getElementById('cancel-demo-reset').onclick=()=>document.getElementById('dialog').close();
  const form=document.getElementById('demo-reset-form');
  form.onsubmit=async event=>{
    event.preventDefault();
    if(form.dataset.pending==='true')return;
    const error=document.getElementById('demo-reset-error');
    error.textContent='';
    setPending(form,true);
    try{
      const out=await api('/auth/demo-reset','POST',{});
      clearSession();
      publicDemo=out.publicDemo===true;
      currentAuth=out.user;
      acceptStore(out.store);
      csrfToken=out.csrf||'';
      authPermissions=out.permissions;
      isSetup=false;
      await refreshData();
      shell();
      toast('เริ่มพื้นที่ทดลองใหม่แล้ว');
    }catch(err){
      if(form.isConnected){error.textContent=err.message;setPending(form,false)}
    }
  };
}

const authenticatedLogout=logout;
logout=async function(){if(publicDemo){showPublicDemoReset();return}return authenticatedLogout()};

const authenticatedUsersView=views.users;
views.users=function(){
  if(!publicDemo)return authenticatedUsersView();
  const rows=[['ดูออเดอร์','ทั้งหมด','เฉพาะข้อมูลจัดส่ง','ดูได้'],['สร้าง / ยกเลิกออเดอร์','ทำได้','—','—'],['กันสต๊อก / หยิบแพ็ก / จัดส่ง','ทำได้','ทำได้','—'],['รับสินค้าเข้า / ดูสต๊อก','ทำได้','ทำได้','—'],['ยอดขาย / ต้นทุน / การเงิน','ดูและส่งออก','—','ดูและส่งออก'],['เชื่อมต่อช่องทางขาย','จัดการได้','—','—'],['บัญชีผู้ใช้และสิทธิ์','จัดการได้','—','—']];
  return `<div class="store-context-note">${icon('users')}<span>ตัวอย่างสิทธิ์ของทีม<small>คุณกำลังลองใช้งานในสิทธิ์ Admin โหมดทดลองไม่ต้องสร้างบัญชีหรือกรอกรหัสผ่าน</small></span></div><div class="user-summary">${Object.keys(roleLabels).map(role=>`<article class="role-card"><h2>${roleLabels[role]}</h2><p>${roleText[role]}</p></article>`).join('')}</div>${panel('สิทธิ์แต่ละระดับ','ระบบใช้งานจริงกำหนดสิทธิ์ให้สมาชิกของแต่ละร้านได้',`<div class="table-scroll"><table class="data-table permissions-table"><thead><tr><th>การใช้งาน</th><th>Admin</th><th>Warehouse</th><th>Finance</th></tr></thead><tbody>${rows.map(row=>`<tr>${row.map((cell,index)=>`<td class="${index&&cell!=='—'?'permission-check':cell==='—'?'permission-no':''}">${cell}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`)}`;
};

const authenticatedStoreView=views.store;
views.store=function(){
  if(!publicDemo)return authenticatedStoreView();
  return `<div class="store-context-note">${icon('box')}<span>ร้านตัวอย่างของคุณ<small>ข้อมูลแยกจากผู้เข้าชมคนอื่น ลองเปลี่ยนชื่อร้านได้โดยใช้ข้อมูลสมมติ</small></span></div><div class="store-grid">${panel('ข้อมูลร้านตัวอย่าง','ลองตั้งชื่อร้านที่แสดงในพื้นที่ทำงาน',`<div class="panel-body"><form id="store-settings-form" class="wizard-fields"><label class="field">ชื่อร้าน<input name="name" value="${esc(currentStore.name)}" maxlength="80" required autocomplete="off"></label><label class="field">รหัสร้านตัวอย่าง<input value="${esc(currentStore.code)}" readonly></label><div class="auth-error" id="store-settings-error" role="alert"></div><div class="actions"><button class="btn primary" type="submit">บันทึกชื่อร้าน</button></div></form></div>`)}${panel('สต๊อกกลางของร้านเดียวกัน','ลองจัดการทุกช่องทางในพื้นที่เดียว',`<div class="panel-body"><p class="section-sub">Facebook, Shopee, TikTok Shop, Lazada, LINE OA, Review และ Offline sales ใช้สินค้าคงคลังกองเดียวกัน</p><div class="wizard-callout"><strong>ข้อมูลสำหรับทดลองเท่านั้น</strong><p>ยังไม่เชื่อมร้านค้าหรือขนส่งจริง และไม่ต้องสร้างบัญชีใหม่ หากต้องการเริ่มลองอีกครั้ง กด “เริ่มใหม่” ที่มุมขวาบน</p></div></div>`)}</div>`;
};

const authenticatedBindStore=bindStore;
bindStore=function(){
  if(!publicDemo){authenticatedBindStore();return}
  const form=document.getElementById('store-settings-form');
  form.onsubmit=async event=>{
    event.preventDefault();
    if(form.dataset.pending==='true')return;
    const error=document.getElementById('store-settings-error');
    error.textContent='';
    setPending(form,true);
    try{
      const out=await api('/store','PATCH',{name:String(new FormData(form).get('name')).trim()});
      if(out.store.id!==currentStore?.id){storeSessionChanged();return}
      acceptStore(out.store);
      shell();
      toast('บันทึกชื่อร้านตัวอย่างแล้ว');
    }catch(err){if(form.isConnected){error.textContent=err.message;setPending(form,false)}}
  };
};

const authenticatedUserForm=showUserForm;
showUserForm=function(user){if(publicDemo){toast('โหมดทดลองไม่ต้องสร้างบัญชีหรือกรอกรหัสผ่าน');return}authenticatedUserForm(user)};
const authenticatedCreateStore=showCreateStore;
showCreateStore=function(){if(publicDemo){toast('คุณมีร้านตัวอย่างของตัวเองแล้ว ลองแก้ชื่อร้านได้');return}authenticatedCreateStore()};
const authenticatedAccount=showAccount;
showAccount=function(){if(publicDemo){showPublicDemoReset();return}authenticatedAccount()};

const authenticatedShell=shell;
shell=function(){
  authenticatedShell();
  document.body.classList.toggle('public-demo-mode',publicDemo&&!!currentAuth);
  if(!publicDemo||!currentAuth)return;
  document.querySelector('.top-right').innerHTML='<span class="demo-badge">โหมดทดลอง</span><button class="btn small demo-reset-button" id="demo-reset">เริ่มใหม่</button>';
  document.getElementById('demo-reset').onclick=showPublicDemoReset;
  const banner=document.createElement('aside');
  banner.className='public-demo-banner';
  banner.setAttribute('aria-label','ข้อมูลโหมดทดลอง');
  banner.innerHTML=`${icon('box')}<div><strong>โหมดทดลอง · ข้อมูลตัวอย่างของคุณ</strong><p>ข้อมูลแยกจากผู้เข้าชมคนอื่น · ใช้ข้อมูลสมมติในการลองใช้งาน</p></div>`;
  document.querySelector('.content').prepend(banner);
  if(state.view==='users'||state.view==='store')document.querySelector('.heading .actions').replaceChildren();
  const footer=document.querySelector('.page-foot');
  footer.innerHTML='<span>Order Hub · ข้อมูลตัวอย่างสมมติ · ยังไม่เชื่อมร้านค้าจริง</span><span>พื้นที่ทดลองของคุณแยกจากผู้เข้าชมคนอื่น</span>';
};
